insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('cuanta-basura-genera-tu-hogar-en-una-semana-y-de-que-esta-hecha','ambiente',array['sociedad']::text[],'¿Cuánta basura genera tu hogar en una semana y de qué está hecha?','Pesa y clasifica durante una semana lo que se tira en tu casa para descubrir cuánta basura se genera y qué parte de ella podría evitarse o aprovecharse.','Análisis','~10 h',10,array['Residuos','Datos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental ingenieria industrial estadistica quimica biologia economia administracion educacion medicion y registro de datos. clasificacion y analisis. graficos. comunicacion de resultados. balanza de cocina o recipientes de volumen conocido. hoja de calculo. bolsas o cajas para clasificar.',$a1sld${"id": "cuanta-basura-genera-tu-hogar-en-una-semana-y-de-que-esta-hecha", "area": "ambiente", "areas2": ["sociedad"], "titulo": "¿Cuánta basura genera tu hogar en una semana y de qué está hecha?", "resumen": "Pesa y clasifica durante una semana lo que se tira en tu casa para descubrir cuánta basura se genera y qué parte de ella podría evitarse o aprovecharse.", "tipo": "Análisis", "tiempo": "~10 h", "horas": 10, "etiquetas": ["Residuos", "Datos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Estadística", "Química", "Biología", "Economía", "Administración", "Educación"], "problema": ["Casi nadie sabe cuánta basura produce su hogar. Las bolsas salen de casa y se pierden de vista, así que lo que se tira se percibe como un volumen vago y no como una cantidad concreta con un origen.", "Sin ese dato es difícil decidir qué cambiar: no es lo mismo que la mayor parte sea comida, envases o papel. Medir permite pasar de la intuición a una conclusión que se pueda comprobar."], "desarrollar": ["Durante siete días separa lo que se tira en categorías simples, como orgánico, plástico, papel y cartón, vidrio y metal, y otros, y pésalo con una balanza de cocina o estima su volumen con un recipiente conocido.", "Ordena los datos por día y por categoría, haz un gráfico que muestre de qué está hecha tu basura y señala qué dos o tres tipos de residuo se podrían reducir con cambios sencillos."], "ampliaciones": [{"titulo": "Comparar semanas", "aporta": "repite la medición otra semana y descubre cuánto varía y por qué."}, {"titulo": "Estimar el año", "aporta": "proyecta tus datos a un año y a todos los hogares de una cuadra para dimensionar el total."}, {"titulo": "Convertirlo en reto", "aporta": "elige una categoría, intenta reducirla y mide cuánto lograste."}], "objetivos": ["Diseñar un método de registro sencillo y repetible.", "Medir y clasificar residuos por categoría.", "Visualizar los resultados con gráficos claros.", "Proponer cambios concretos basados en los datos."], "habilidades": ["Medición y registro de datos.", "Clasificación y análisis.", "Gráficos.", "Comunicación de resultados."], "herramientas": ["Balanza de cocina o recipientes de volumen conocido.", "Hoja de cálculo.", "Bolsas o cajas para clasificar."], "lineamientos": ["Usa guantes al clasificar, no manipules residuos punzocortantes ni de higiene personal, y lávate las manos al terminar.", "Registra cantidades y tipos de residuo, no a las personas que los generaron; presenta los resultados sin juzgar a nadie."], "otroSector": "La misma medición sirve en un colegio, un restaurante, una oficina o un mercado, y también para estimar cuánta agua, energía o papel se usa en un espacio."}$a1sld$::jsonb,9),
('que-reciclables-terminan-en-la-basura-por-falta-de-informacion','ambiente',array['educacion']::text[],'¿Qué reciclables terminan en la basura por falta de información?','Descubre qué materiales que sí podrían reciclarse acaban en la basura común por dudas o desconocimiento, y qué información los haría separarse mejor.','Investigación','~15 h',15,array['Reciclaje','Información']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental educacion comunicaciones psicologia sociologia quimica ingenieria industrial estadistica observacion y registro. lectura de fuentes oficiales. diseno de informacion. comunicacion clara. cuaderno o formulario de registro. guias publicas de reciclaje. un editor de carteles o de presentaciones.',$a2sld${"id": "que-reciclables-terminan-en-la-basura-por-falta-de-informacion", "area": "ambiente", "areas2": ["educacion"], "titulo": "¿Qué reciclables terminan en la basura por falta de información?", "resumen": "Descubre qué materiales que sí podrían reciclarse acaban en la basura común por dudas o desconocimiento, y qué información los haría separarse mejor.", "tipo": "Investigación", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Reciclaje", "Información"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Educación", "Comunicaciones", "Psicología", "Sociología", "Química", "Ingeniería Industrial", "Estadística"], "problema": ["Muchas personas quieren reciclar, pero no saben con certeza qué va en cada lugar: si un envase sucio sirve, si una caja de jugo se recicla o si el papel con grasa puede separarse. Ante la duda, se tira todo junto.", "Esa falta de información hace que materiales aprovechables se pierdan, y a veces que lo mal separado contamine lo que sí estaba bien. El problema no siempre es de voluntad, sino de claridad."], "desarrollar": ["Revisa durante una semana los residuos de tu casa o de un espacio al que tengas acceso, anota cuáles eran potencialmente reciclables según la información pública de tu localidad o de un programa de reciclaje, y cuáles terminaron en el tacho equivocado.", "Agrupa las causas, como duda sobre el material, suciedad o falta de un lugar para separar, y prepara una ayuda visual breve para los tres materiales que más se confunden."], "ampliaciones": [{"titulo": "Probar la ayuda", "aporta": "muestra tu material a algunas personas y comprueba si ahora clasifican mejor."}, {"titulo": "Comparar fuentes", "aporta": "contrasta las instrucciones de distintas fuentes y detecta dónde se contradicen."}, {"titulo": "Un cartel claro", "aporta": "diseña un cartel para un tacho de reciclaje que se entienda en cinco segundos."}], "objetivos": ["Identificar qué reciclables se desechan mal.", "Reconocer las causas de la confusión.", "Consultar fuentes oficiales para saber cómo clasificar.", "Diseñar una ayuda visual clara."], "habilidades": ["Observación y registro.", "Lectura de fuentes oficiales.", "Diseño de información.", "Comunicación clara."], "herramientas": ["Cuaderno o formulario de registro.", "Guías públicas de reciclaje.", "Un editor de carteles o de presentaciones."], "lineamientos": ["Basa tus indicaciones en fuentes oficiales de tu localidad y cítalas: las reglas de reciclaje cambian según el lugar.", "Registra tipos de residuo y no a personas, y manipula los residuos con guantes y sin tocar punzocortantes."], "otroSector": "El mismo método sirve para estudiar por qué las personas se equivocan al seguir instrucciones en trámites, etiquetas, formularios o aplicaciones."}$a2sld$::jsonb,10),
('disena-un-sistema-para-separar-y-aprovechar-los-residuos-de-un-h','ambiente',array['industria']::text[],'Diseña un sistema para separar y aprovechar los residuos de un hogar','Diseña un sistema práctico para separar los residuos de una vivienda y decidir qué hacer con cada tipo, adaptado a un espacio pequeño y a una rutina real.','Prototipo','~20 h',20,array['Residuos','Diseño']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria industrial ingenieria ambiental arquitectura diseno grafico ingenieria mecanica ingenieria civil administracion educacion diseno de procesos. diseno de espacios. pensamiento sistemico. comunicacion visual. papel o una herramienta de planos y diagramas. hoja de calculo para costos. un editor de diagramas de flujo.',$a3sld${"id": "disena-un-sistema-para-separar-y-aprovechar-los-residuos-de-un-h", "area": "ambiente", "areas2": ["industria"], "titulo": "Diseña un sistema para separar y aprovechar los residuos de un hogar", "resumen": "Diseña un sistema práctico para separar los residuos de una vivienda y decidir qué hacer con cada tipo, adaptado a un espacio pequeño y a una rutina real.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Residuos", "Diseño"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Industrial", "Ingeniería Ambiental", "Arquitectura", "Diseño Gráfico", "Ingeniería Mecánica", "Ingeniería Civil", "Administración", "Educación"], "problema": ["Separar residuos suena simple, pero en casas y departamentos pequeños faltan lugares donde guardar los distintos materiales, y cuando separar es incómodo, se deja de hacer. Muchos sistemas están pensados para espacios amplios.", "Un buen sistema no solo clasifica: también define dónde se guarda cada cosa, cada cuánto se saca y a dónde va después. Si una de esas piezas falla, todo el esquema se cae."], "desarrollar": ["Elige un tipo de vivienda, real o ficticio, y define qué materiales se separarán, dónde estarán los recipientes, quién se encargará y qué pasa con cada material: reutilizar, compostar, reciclar o desechar.", "Presenta el sistema como un plano o esquema con recipientes y flujo de residuos, una guía de una página para las personas de la casa y una lista de qué materiales y costos necesitaría."], "ampliaciones": [{"titulo": "Otro tipo de hogar", "aporta": "adapta el sistema a una casa grande, un cuarto alquilado o un departamento compartido."}, {"titulo": "Ahorro y valor", "aporta": "estima qué parte de los residuos se aprovecharía y cuánto se evitaría tirar."}, {"titulo": "Prueba de uso", "aporta": "arma una maqueta sencilla y observa si alguien la usa sin explicación."}], "objetivos": ["Definir qué materiales se separan y por qué.", "Diseñar el espacio y el recorrido de los residuos.", "Redactar instrucciones claras.", "Evaluar si el sistema es práctico para un hogar real."], "habilidades": ["Diseño de procesos.", "Diseño de espacios.", "Pensamiento sistémico.", "Comunicación visual."], "herramientas": ["Papel o una herramienta de planos y diagramas.", "Hoja de cálculo para costos.", "Un editor de diagramas de flujo."], "lineamientos": ["No mezcles ni almacenes sustancias peligrosas como pilas, solventes o medicamentos; indica que deben entregarse en puntos autorizados.", "Si probarás el sistema en una casa, hazlo con quienes vivan allí y con su acuerdo, y ajusta si no resulta cómodo."], "otroSector": "La misma lógica sirve para diseñar el manejo de residuos de un negocio pequeño, un aula, un evento o un taller."}$a3sld$::jsonb,11),
('que-residuos-de-una-institucion-podrian-aprovecharse-en-lugar-de','ambiente',array['industria','negocios']::text[],'¿Qué residuos de una institución podrían aprovecharse en lugar de desecharse?','Observa qué se tira en una institución y descubre qué materiales podrían reutilizarse, donarse o transformarse en vez de convertirse en basura.','Análisis','~20 h',20,array['Residuos','Economía circular']::text[],array['investigar','resolver','otro-sector']::text[],'propios',NULL,'ingenieria ambiental ingenieria industrial administracion economia quimica arquitectura educacion contabilidad observacion sistematica. analisis de residuos. pensamiento de economia circular. presentacion de resultados. fichas de registro. hoja de calculo. un editor de presentaciones.',$a4sld${"id": "que-residuos-de-una-institucion-podrian-aprovecharse-en-lugar-de", "area": "ambiente", "areas2": ["industria", "negocios"], "titulo": "¿Qué residuos de una institución podrían aprovecharse en lugar de desecharse?", "resumen": "Observa qué se tira en una institución y descubre qué materiales podrían reutilizarse, donarse o transformarse en vez de convertirse en basura.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Residuos", "Economía circular"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Administración", "Economía", "Química", "Arquitectura", "Educación", "Contabilidad"], "problema": ["Colegios, universidades, oficinas o talleres desechan a diario papel, restos de comida, muebles, cartuchos, envases o materiales de laboratorio que todavía podrían servir a alguien. Como la basura se retira rápido, rara vez se mira lo que contiene.", "Sin esa mirada, se pierden materiales que tienen valor y se paga por desecharlos. Algunos residuos de un lugar son justamente lo que otro necesita."], "desarrollar": ["Elige un espacio al que tengas acceso, avisa y pide permiso, y observa durante una semana qué se desecha en tres puntos, como aulas, oficinas o comedor. Registra tipos y cantidades aproximadas, no personas.", "Para cada tipo de residuo, propón un posible uso alternativo, como reutilizar, donar o transformar, y arma una tabla que muestre qué residuos tienen más potencial y qué haría falta para aprovecharlos."], "ampliaciones": [{"titulo": "Valor del residuo", "aporta": "estima cuánto dinero representan los materiales que hoy se desechan."}, {"titulo": "Buscar destinatarios", "aporta": "identifica quién podría necesitar cada material, como una escuela, un taller o una organización."}, {"titulo": "Plan piloto", "aporta": "diseña una prueba pequeña para aprovechar un solo tipo de residuo durante un mes."}], "objetivos": ["Observar y registrar qué se desecha.", "Clasificar los residuos por potencial de aprovechamiento.", "Proponer usos alternativos viables.", "Presentar los hallazgos con orden."], "habilidades": ["Observación sistemática.", "Análisis de residuos.", "Pensamiento de economía circular.", "Presentación de resultados."], "herramientas": ["Fichas de registro.", "Hoja de cálculo.", "Un editor de presentaciones."], "lineamientos": ["Pide autorización antes de observar o fotografiar un espacio y no registres a las personas ni lo que cada una desecha.", "Presenta los resultados como oportunidades de mejora, sin señalar responsables."], "otroSector": "El mismo análisis sirve para una oficina, un hospital, un restaurante, un mercado o un evento, y para otros recursos como energía o agua."}$a4sld$::jsonb,12),
('el-viaje-de-tus-residuos-a-donde-van-al-salir-de-casa','ambiente',array['ciudades','sociedad']::text[],'El viaje de tus residuos: ¿a dónde van al salir de casa?','Sigue el recorrido de la basura de tu zona, desde el tacho hasta su destino final, con información pública, y descubre qué ocurre en cada etapa.','Investigación','~20 h',20,array['Residuos','Gestión']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria ambiental ingenieria civil geografia sociologia derecho administracion ingenieria industrial estadistica investigacion de fuentes. representacion de procesos. pensamiento critico. redaccion clara. portales y reportes publicos de gestion de residuos. un mapa digital. un editor de diagramas.',$a5sld${"id": "el-viaje-de-tus-residuos-a-donde-van-al-salir-de-casa", "area": "ambiente", "areas2": ["ciudades", "sociedad"], "titulo": "El viaje de tus residuos: ¿a dónde van al salir de casa?", "resumen": "Sigue el recorrido de la basura de tu zona, desde el tacho hasta su destino final, con información pública, y descubre qué ocurre en cada etapa.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Residuos", "Gestión"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Civil", "Geografía", "Sociología", "Derecho", "Administración", "Ingeniería Industrial", "Estadística"], "problema": ["Cuando la bolsa sale de casa, la mayoría deja de saber qué pasa con ella. Hay quienes la recogen, vehículos que la trasladan y lugares donde termina, y cada etapa tiene costos, riesgos y personas involucradas.", "Conocer ese recorrido cambia la manera de mirar los residuos: permite entender por qué separar importa, qué se pierde en el camino y quién se encarga de cada paso."], "desarrollar": ["Con información pública de tu municipalidad y de las instituciones responsables, reconstruye el recorrido de los residuos de tu distrito: recojo, traslado, tratamiento o disposición final, con frecuencias, responsables y lugares.", "Preséntalo como un diagrama o un mapa sencillo, anota qué datos no encontraste y qué preguntas quedan abiertas para quien administra el servicio."], "ampliaciones": [{"titulo": "Comparar zonas", "aporta": "contrasta el recorrido de dos distritos distintos y busca qué los diferencia."}, {"titulo": "Volver a casa", "aporta": "calcula cuánto recorre en promedio un residuo y qué costo tiene su traslado."}, {"titulo": "Contarlo a otros", "aporta": "convierte el recorrido en un video corto o en una infografía para tu comunidad."}], "objetivos": ["Buscar y verificar información pública.", "Reconstruir las etapas del recorrido.", "Representarlas en un diagrama o mapa.", "Identificar vacíos de información."], "habilidades": ["Investigación de fuentes.", "Representación de procesos.", "Pensamiento crítico.", "Redacción clara."], "herramientas": ["Portales y reportes públicos de gestión de residuos.", "Un mapa digital.", "Un editor de diagramas."], "lineamientos": ["Cita cada fuente y distingue lo que está documentado de lo que supones; si falta un dato, dilo en lugar de estimarlo sin avisar.", "No visites ni fotografíes botaderos u otras instalaciones sin autorización: trabaja con información pública."], "otroSector": "El mismo seguimiento sirve para estudiar el recorrido del agua, de un producto, de un trámite o de una cadena de suministro."}$a5sld$::jsonb,13),
('mapa-de-puntos-de-reciclaje-de-tu-comunidad','ambiente',array['ciudades','tecnologia']::text[],'Mapa de puntos de reciclaje de tu comunidad','Reúne en un mapa claro dónde llevar cada tipo de residuo en tu zona, con horarios y condiciones verificadas, para que reciclar sea fácil de encontrar.','Prototipo','~18 h',18,array['Reciclaje','Mapas']::text[],array['crear','resolver']::text[],'publicos',NULL,'ingenieria de sistemas geografia ingenieria ambiental ingenieria civil comunicaciones diseno grafico administracion ciencia de datos busqueda y verificacion de informacion. representacion en mapas. organizacion de datos. pruebas con usuarios. hoja de calculo. un editor de mapas digitales. un formulario de prueba.',$a6sld${"id": "mapa-de-puntos-de-reciclaje-de-tu-comunidad", "area": "ambiente", "areas2": ["ciudades", "tecnologia"], "titulo": "Mapa de puntos de reciclaje de tu comunidad", "resumen": "Reúne en un mapa claro dónde llevar cada tipo de residuo en tu zona, con horarios y condiciones verificadas, para que reciclar sea fácil de encontrar.", "tipo": "Prototipo", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Reciclaje", "Mapas"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería de Sistemas", "Geografía", "Ingeniería Ambiental", "Ingeniería Civil", "Comunicaciones", "Diseño Gráfico", "Administración", "Ciencia de Datos"], "problema": ["Aunque existan centros de acopio, campañas y recicladores formales, su información está dispersa en páginas, redes y carteles, y a veces desactualizada. Quien quiere reciclar no sabe a dónde ir ni qué aceptan.", "Cuando encontrar el lugar cuesta tanto esfuerzo, reciclar pasa a ser algo ocasional. Un mapa útil necesita datos verificados, no solo puntos."], "desarrollar": ["Reúne información pública de diez a quince puntos de tu zona, como centros de acopio, campañas o programas, y registra qué materiales reciben, horarios, condiciones y fecha de verificación.", "Ubícalos en un mapa digital con filtros por tipo de material y compruébalo pidiendo a dos personas que busquen dónde llevar algo concreto, como pilas o papel."], "ampliaciones": [{"titulo": "Detectar vacíos", "aporta": "identifica qué materiales no tienen ningún punto cercano."}, {"titulo": "Versión imprimible", "aporta": "crea una versión de una hoja para repartir en un edificio o colegio."}, {"titulo": "Mantenerlo vivo", "aporta": "diseña cómo se revisaría y actualizaría la información cada cierto tiempo."}], "objetivos": ["Reunir información verificable de puntos de reciclaje.", "Organizarla con criterios claros.", "Representarla en un mapa útil.", "Probarlo con personas."], "habilidades": ["Búsqueda y verificación de información.", "Representación en mapas.", "Organización de datos.", "Pruebas con usuarios."], "herramientas": ["Hoja de cálculo.", "Un editor de mapas digitales.", "Un formulario de prueba."], "lineamientos": ["Verifica cada punto en su fuente oficial y anota la fecha: horarios y materiales cambian con frecuencia.", "Incluye solo servicios formales y autorizados, y no recomiendes manipular residuos peligrosos por tu cuenta."], "otroSector": "El mismo mapa sirve para ubicar servicios de salud, bibliotecas, espacios deportivos, bancos de alimentos o puntos de ayuda."}$a6sld$::jsonb,14),
('reto-una-semana-generando-menos-residuos','ambiente',array['sociedad']::text[],'Reto: una semana generando menos residuos','Mide cuánto generas normalmente, cambia algunos hábitos durante una semana y comprueba cuánto lograste reducir, con datos y sin exigirte la perfección.','Plan','~12 h',12,array['Reto','Hábitos']::text[],array['resolver','crear']::text[],'propios',NULL,'ingenieria ambiental psicologia educacion comunicaciones administracion estadistica nutricion ingenieria industrial medicion y registro. diseno de habitos. analisis comparativo. comunicacion de resultados. hoja de calculo o cuaderno. balanza de cocina. una aplicacion de seguimiento de habitos.',$a7sld${"id": "reto-una-semana-generando-menos-residuos", "area": "ambiente", "areas2": ["sociedad"], "titulo": "Reto: una semana generando menos residuos", "resumen": "Mide cuánto generas normalmente, cambia algunos hábitos durante una semana y comprueba cuánto lograste reducir, con datos y sin exigirte la perfección.", "tipo": "Plan", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Reto", "Hábitos"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Psicología", "Educación", "Comunicaciones", "Administración", "Estadística", "Nutrición", "Ingeniería Industrial"], "problema": ["Hablar de reducir residuos suele quedarse en buenas intenciones porque no se sabe por dónde empezar ni se comprueba si algo cambió. Los consejos genéricos no se adaptan a la rutina de cada persona.", "Un reto con medición permite saber qué sí cuesta poco y funciona, y qué es poco realista para tu vida, en lugar de culparte por no lograrlo."], "desarrollar": ["Mide una semana de referencia, elige tres hábitos concretos que puedas cambiar, como llevar tu propio recipiente, planificar compras o rechazar envoltorios, y repite la medición durante otra semana.", "Compara ambas semanas, anota qué cambio resultó fácil y cuál difícil y por qué, y cierra con una conclusión honesta sobre qué mantendrías."], "ampliaciones": [{"titulo": "Reto en grupo", "aporta": "invita a un grupo pequeño y compara qué hábitos funcionaron mejor."}, {"titulo": "Registro visual", "aporta": "arma un tablero diario para ver el progreso de un vistazo."}, {"titulo": "Guía de lo aprendido", "aporta": "resume los hábitos que funcionaron en una guía para otra persona."}], "objetivos": ["Establecer una línea base medible.", "Elegir cambios realistas.", "Comparar resultados entre semanas.", "Reflexionar sobre qué sostener."], "habilidades": ["Medición y registro.", "Diseño de hábitos.", "Análisis comparativo.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo o cuaderno.", "Balanza de cocina.", "Una aplicación de seguimiento de hábitos."], "lineamientos": ["No cambies hábitos que afecten tu salud o seguridad, como la higiene de los alimentos, solo por reducir residuos.", "Presenta tus resultados como una experiencia personal, no como un modelo para todos."], "otroSector": "El mismo esquema sirve para retos de ahorro de agua, energía, dinero, tiempo de pantalla o consumo de papel."}$a7sld$::jsonb,15),
('cuanto-plastico-de-un-solo-uso-pasa-por-tus-manos','ambiente',array['sociedad']::text[],'¿Cuánto plástico de un solo uso pasa por tus manos?','Cuenta durante una semana los objetos de plástico de un solo uso que usas, descubre cuáles son más fáciles de reemplazar y cuánto cambiaría si lo hicieras.','Análisis','~12 h',12,array['Plástico','Hábitos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental quimica ingenieria quimica biologia educacion comunicaciones estadistica ingenieria industrial registro y conteo. analisis comparativo. evaluacion de alternativas. comunicacion de resultados. hoja de calculo. cuaderno de registro. un editor de graficos.',$a8sld${"id": "cuanto-plastico-de-un-solo-uso-pasa-por-tus-manos", "area": "ambiente", "areas2": ["sociedad"], "titulo": "¿Cuánto plástico de un solo uso pasa por tus manos?", "resumen": "Cuenta durante una semana los objetos de plástico de un solo uso que usas, descubre cuáles son más fáciles de reemplazar y cuánto cambiaría si lo hicieras.", "tipo": "Análisis", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Plástico", "Hábitos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Química", "Ingeniería Química", "Biología", "Educación", "Comunicaciones", "Estadística", "Ingeniería Industrial"], "problema": ["Bolsas, sorbetes, botellas, cubiertos y envoltorios se usan unos minutos y duran muchos años. Como cada uno parece insignificante, casi nadie sabe cuántos usa en total.", "Sin ese conteo, los cambios suelen ser simbólicos: se reemplaza lo más visible y se pasa por alto lo que más se acumula."], "desarrollar": ["Durante una semana registra cada objeto de plástico de un solo uso que uses, con su tipo y la situación en que apareció, como comprar comida, viajar o estudiar.", "Ordena los resultados, identifica los cinco más frecuentes, busca una alternativa realista para cada uno, incluyendo su costo, y estima cuántos se evitarían en un año."], "ampliaciones": [{"titulo": "Comparar entornos", "aporta": "compara el uso en casa, en la universidad y en la calle."}, {"titulo": "Alternativas reales", "aporta": "compara la durabilidad y el costo de una alternativa reutilizable frente al desechable."}, {"titulo": "Mapa del plástico", "aporta": "dibuja de dónde proviene cada objeto y a dónde va cuando lo desechas."}], "objetivos": ["Registrar el consumo de plástico de manera sistemática.", "Identificar qué objetos dominan.", "Evaluar alternativas con criterios claros.", "Estimar el efecto de los cambios."], "habilidades": ["Registro y conteo.", "Análisis comparativo.", "Evaluación de alternativas.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Cuaderno de registro.", "Un editor de gráficos."], "lineamientos": ["Evita afirmar que una alternativa es siempre mejor sin considerar cuántas veces se usa: una bolsa o botella reutilizable ayuda solo si se utiliza muchas veces.", "No generalices a partir de tus datos: son un caso personal, no un promedio."], "otroSector": "El mismo conteo sirve para papel, agua embotellada, ropa nueva, dispositivos o cualquier consumo repetido."}$a8sld$::jsonb,16),
('propuesta-para-reducir-los-desechables-en-una-institucion','ambiente',array['negocios','sociedad']::text[],'Propuesta para reducir los desechables en una institución','Diseña una propuesta realista para que un comedor, kiosco, oficina o evento reduzca el uso de vasos, platos, cubiertos y bolsas descartables sin perder comodidad.','Plan','~22 h',22,array['Desechables','Propuesta']::text[],array['resolver','crear','otro-sector']::text[],'ficticios',NULL,'administracion ingenieria industrial ingenieria ambiental economia comunicaciones contabilidad psicologia educacion diseno de propuestas. analisis de costos. gestion del cambio. comunicacion persuasiva. hoja de calculo. un editor de presentaciones. un editor de diagramas.',$a9sld${"id": "propuesta-para-reducir-los-desechables-en-una-institucion", "area": "ambiente", "areas2": ["negocios", "sociedad"], "titulo": "Propuesta para reducir los desechables en una institución", "resumen": "Diseña una propuesta realista para que un comedor, kiosco, oficina o evento reduzca el uso de vasos, platos, cubiertos y bolsas descartables sin perder comodidad.", "tipo": "Plan", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Desechables", "Propuesta"], "intencion": ["resolver", "crear", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Administración", "Ingeniería Industrial", "Ingeniería Ambiental", "Economía", "Comunicaciones", "Contabilidad", "Psicología", "Educación"], "problema": ["Los desechables resuelven rápido el servicio y reducen la limpieza, y por eso se usan en cafeterías, eventos y oficinas. Pero generan residuos constantes y costos que no siempre se ven.", "Cambiarlos no es solo decidir: hay que pensar en lavado, espacio, costo y hábitos de las personas. Las propuestas que ignoran esos detalles terminan abandonadas."], "desarrollar": ["Elige un caso concreto, real o inventado, como un kiosco, un comedor o un evento de la facultad, describe cómo funciona hoy y cuántos desechables se usarían en un mes.", "Propón un plan por etapas con alternativas, el costo y ahorro estimados, los cambios de rutina necesarios y cómo se informaría a las personas, y comprueba que cada paso sea viable."], "ampliaciones": [{"titulo": "Costo real", "aporta": "calcula el costo mensual de los desechables frente a las alternativas reutilizables."}, {"titulo": "Mensaje y señalización", "aporta": "diseña carteles o mensajes que animen a usar lo reutilizable."}, {"titulo": "Medir resultados", "aporta": "define indicadores para saber si el plan funciona y cómo se registrarían."}], "objetivos": ["Describir la situación actual con cifras razonables.", "Evaluar alternativas realistas.", "Elaborar un plan por etapas.", "Plantear cómo medir si funciona."], "habilidades": ["Diseño de propuestas.", "Análisis de costos.", "Gestión del cambio.", "Comunicación persuasiva."], "herramientas": ["Hoja de cálculo.", "Un editor de presentaciones.", "Un editor de diagramas."], "lineamientos": ["Si trabajas con un caso real, pide permiso para observarlo y no publiques datos de personas ni de empresas sin su acuerdo.", "Considera siempre la higiene y la seguridad de los alimentos: reducir desechables no debe poner en riesgo la salud."], "otroSector": "La misma propuesta sirve para reducir papel, energía, agua o transporte en una empresa, un colegio o un evento."}$a9sld$::jsonb,17),
('el-ciclo-de-vida-de-un-producto-cotidiano-envase-incluido','ambiente',array['industria','ciencias']::text[],'El ciclo de vida de un producto cotidiano, envase incluido','Elige un producto que usas a diario y reconstruye su recorrido: de qué está hecho, cómo se produce, cómo llega a ti, para qué lo usas y qué pasa con él y su envase al final.','Investigación','~25 h',25,array['Ciclo de vida','Productos']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria ambiental ingenieria industrial ingenieria quimica quimica economia administracion ingenieria mecanica estadistica investigacion de fuentes. pensamiento sistemico. analisis comparativo. esquemas y visualizacion. informes y bases de datos publicas de ciclo de vida. un editor de diagramas. hoja de calculo.',$a10sld${"id": "el-ciclo-de-vida-de-un-producto-cotidiano-envase-incluido", "area": "ambiente", "areas2": ["industria", "ciencias"], "titulo": "El ciclo de vida de un producto cotidiano, envase incluido", "resumen": "Elige un producto que usas a diario y reconstruye su recorrido: de qué está hecho, cómo se produce, cómo llega a ti, para qué lo usas y qué pasa con él y su envase al final.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Ciclo de vida", "Productos"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Ingeniería Química", "Química", "Economía", "Administración", "Ingeniería Mecánica", "Estadística"], "problema": ["Un producto cotidiano, como una botella, una polera o un cuaderno, parece simple, pero detrás hay materias primas, fabricación, transporte, uso y desecho. Cada etapa tiene un costo ambiental distinto.", "Mirar solo el momento de desechar da una imagen incompleta: a veces lo que más impacta ocurre antes de que el producto llegue a las manos."], "desarrollar": ["Elige un producto y su envase, y con información pública documenta cada etapa: materiales, producción, transporte, uso y fin de vida, indicando qué datos son estimaciones.", "Presenta el ciclo en un esquema por etapas y marca en cuáles parece concentrarse el mayor impacto, con las dudas que quedan abiertas."], "ampliaciones": [{"titulo": "Comparar dos productos", "aporta": "compara dos alternativas que sirven para lo mismo, como una botella descartable y una reutilizable."}, {"titulo": "Ver el envase", "aporta": "analiza solo el envase y qué alternativas existen."}, {"titulo": "Contarlo en un video", "aporta": "convierte el ciclo en un recorrido ilustrado de dos minutos."}], "objetivos": ["Investigar el origen y el fin de un producto.", "Estructurar su ciclo de vida.", "Identificar las etapas de mayor impacto.", "Reconocer los límites de los datos."], "habilidades": ["Investigación de fuentes.", "Pensamiento sistémico.", "Análisis comparativo.", "Esquemas y visualización."], "herramientas": ["Informes y bases de datos públicas de ciclo de vida.", "Un editor de diagramas.", "Hoja de cálculo."], "lineamientos": ["Cita cada dato y evita presentar cifras inventadas: si algo es una estimación, dilo y explica cómo la hiciste.", "No concluyas que un producto es bueno o malo en general; limita tus conclusiones a lo que puedes sustentar."], "otroSector": "El mismo análisis sirve para estudiar un servicio, un edificio, un alimento, un software o un proceso de una empresa."}$a10sld$::jsonb,18),
('que-tan-verdes-son-tus-compras','ambiente',array['negocios']::text[],'¿Qué tan verdes son tus compras?','Revisa lo que compras durante unas semanas y descubre qué parte de tus compras es necesaria, cuánto envase generan y dónde podrías elegir mejor sin gastar más.','Análisis','~15 h',15,array['Consumo','Compras']::text[],array['investigar','resolver']::text[],'propios',NULL,'economia administracion ingenieria ambiental ingenieria industrial contabilidad estadistica psicologia comunicaciones registro de datos. analisis de decisiones de consumo. comparacion de alternativas. comunicacion de resultados. hoja de calculo. boletas o registros de compra. un editor de graficos.',$a11sld${"id": "que-tan-verdes-son-tus-compras", "area": "ambiente", "areas2": ["negocios"], "titulo": "¿Qué tan verdes son tus compras?", "resumen": "Revisa lo que compras durante unas semanas y descubre qué parte de tus compras es necesaria, cuánto envase generan y dónde podrías elegir mejor sin gastar más.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Consumo", "Compras"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Economía", "Administración", "Ingeniería Ambiental", "Ingeniería Industrial", "Contabilidad", "Estadística", "Psicología", "Comunicaciones"], "problema": ["Lo que se compra cada día termina definiendo mucho del impacto ambiental de una persona, pero rara vez se revisa. Se compra por costumbre, por promoción o por comodidad, sin pensar en el envase, el origen o cuánto durará.", "No se trata de comprar menos a cualquier costo, sino de saber qué decisiones pesan más y cuáles se pueden mejorar con poco esfuerzo."], "desarrollar": ["Registra durante dos o tres semanas lo que compras, con qué envase vino y si lo usaste o lo desechaste pronto. Clasifícalo en necesario, ocasional y prescindible.", "Elige las cinco compras más frecuentes, busca una alternativa más duradera, con menos envase o más local para cada una, y compara su costo y comodidad."], "ampliaciones": [{"titulo": "Compras de un mes", "aporta": "convierte tus registros en un resumen mensual con gráficos."}, {"titulo": "Reto de 30 días", "aporta": "intenta cambiar tres compras habituales durante un mes y mide el resultado."}, {"titulo": "Comparar tiendas", "aporta": "compara cómo cambia el envase y el precio de lo mismo en distintos lugares."}], "objetivos": ["Registrar compras de forma ordenada.", "Clasificar lo necesario y lo prescindible.", "Evaluar alternativas con criterios claros.", "Elegir cambios realistas y comprobar su efecto."], "habilidades": ["Registro de datos.", "Análisis de decisiones de consumo.", "Comparación de alternativas.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Boletas o registros de compra.", "Un editor de gráficos."], "lineamientos": ["No registres información bancaria ni datos personales; basta con producto, categoría y monto aproximado.", "No promociones ni desacredites marcas; compara tipos de producto y características verificables."], "otroSector": "El mismo análisis sirve para estudiar gastos de un negocio, de una organización estudiantil o de un evento."}$a11sld$::jsonb,19),
('crea-una-guia-de-consumo-responsable','ambiente',array['arte','educacion']::text[],'Crea una guía de consumo responsable','Elabora una guía breve y atractiva que ayude a una persona a consumir con más criterio: qué preguntarse antes de comprar y cómo cuidar lo que ya tiene.','Guía','~18 h',18,array['Consumo','Guía']::text[],array['crear','resolver']::text[],'ficticios',NULL,'diseno grafico comunicaciones publicidad educacion ingenieria ambiental economia psicologia administracion redaccion clara. diseno de informacion. pruebas con usuarios. pensamiento critico. un editor de diseno o de presentaciones. un formulario para probar con lectores. hoja de calculo.',$a12sld${"id": "crea-una-guia-de-consumo-responsable", "area": "ambiente", "areas2": ["arte", "educacion"], "titulo": "Crea una guía de consumo responsable", "resumen": "Elabora una guía breve y atractiva que ayude a una persona a consumir con más criterio: qué preguntarse antes de comprar y cómo cuidar lo que ya tiene.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Consumo", "Guía"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Diseño Gráfico", "Comunicaciones", "Publicidad", "Educación", "Ingeniería Ambiental", "Economía", "Psicología", "Administración"], "problema": ["Las guías de consumo responsable suelen ser listas largas de lo que no hay que hacer, y casi nadie las sigue. Son difíciles de recordar y rara vez se adaptan a la vida de quien las lee.", "Una buena guía ayuda a decidir en el momento justo, con pocas preguntas claras y alternativas que se pueden lograr."], "desarrollar": ["Elige un público concreto, como estudiantes o familias, y define de tres a cinco preguntas que ayuden a decidir antes de comprar, como si lo necesito, cuánto durará y qué pasa con el envase.", "Diséñala en una hoja o tarjeta clara, con ejemplos de la vida cotidiana, y pide a dos o tres personas que la lean y digan qué no entendieron para mejorarla."], "ampliaciones": [{"titulo": "Para otro público", "aporta": "adapta la guía para niños, adultos mayores o personas con presupuesto muy ajustado."}, {"titulo": "Versión en imágenes", "aporta": "crea una versión casi sin texto, con ilustraciones."}, {"titulo": "Probar la guía", "aporta": "comprueba con una pequeña encuesta si ayudó a decidir distinto."}], "objetivos": ["Elegir un público y un propósito.", "Redactar preguntas claras y breves.", "Diseñar una pieza atractiva.", "Probarla y mejorarla."], "habilidades": ["Redacción clara.", "Diseño de información.", "Pruebas con usuarios.", "Pensamiento crítico."], "herramientas": ["Un editor de diseño o de presentaciones.", "Un formulario para probar con lectores.", "Hoja de cálculo."], "lineamientos": ["Evita tonos de culpa o de regaño: la guía debe sentirse como una ayuda y no como un reproche.", "No des por hecho que todos pueden pagar alternativas más caras; incluye opciones de bajo costo."], "otroSector": "La misma estructura sirve para guías de ahorro de energía, de uso responsable de tecnología, de finanzas personales o de salud preventiva."}$a12sld$::jsonb,20),
('reparar-o-reemplazar-el-impacto-de-cada-decision','ambiente',array['negocios','industria']::text[],'¿Reparar o reemplazar? El impacto de cada decisión','Compara el costo y el impacto ambiental de reparar un objeto frente a comprar uno nuevo, para saber en qué casos conviene cada decisión.','Análisis','~18 h',18,array['Reparación','Consumo']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria ambiental ingenieria industrial ingenieria mecanica economia administracion contabilidad estadistica ingenieria electronica analisis de costos y beneficios. busqueda de datos. modelado simple. comunicacion de resultados. hoja de calculo. precios publicados y resenas de duracion. estudios publicos sobre impacto de fabricacion.',$a13sld${"id": "reparar-o-reemplazar-el-impacto-de-cada-decision", "area": "ambiente", "areas2": ["negocios", "industria"], "titulo": "¿Reparar o reemplazar? El impacto de cada decisión", "resumen": "Compara el costo y el impacto ambiental de reparar un objeto frente a comprar uno nuevo, para saber en qué casos conviene cada decisión.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Reparación", "Consumo"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Ingeniería Mecánica", "Economía", "Administración", "Contabilidad", "Estadística", "Ingeniería Electrónica"], "problema": ["Cuando algo se malogra, reemplazarlo suele parecer más rápido o incluso más barato. Pero fabricar un objeto nuevo requiere materiales, energía y transporte, y el objeto viejo se vuelve residuo.", "A veces reparar conviene y a veces no: depende de cuánto cuesta, cuánto le queda de vida útil y cuánto pesa su impacto de fabricación. Esa cuenta rara vez se hace."], "desarrollar": ["Elige tres objetos comunes, como zapatos, un electrodoméstico pequeño o una mochila, y busca cuánto cuesta repararlos, cuánto cuesta uno nuevo y cuánto suele durar cada opción, con precios y fuentes que puedas citar.", "Construye una tabla o regla simple de decisión, por ejemplo en qué punto de costo o de antigüedad conviene reparar, y explica qué impacto ambiental adicional se evita al hacerlo según fuentes públicas."], "ampliaciones": [{"titulo": "Calculadora de decisión", "aporta": "crea una hoja de cálculo donde se ingresen precios y duración y sugiera qué conviene."}, {"titulo": "Ver el taller", "aporta": "recopila qué talleres de reparación existen en tu zona y qué reparan."}, {"titulo": "Otra perspectiva", "aporta": "analiza qué cambia si el objeto es de segunda mano."}], "objetivos": ["Reunir datos de costos y duración.", "Comparar escenarios con criterios claros.", "Construir una regla de decisión.", "Explicar los límites de las estimaciones."], "habilidades": ["Análisis de costos y beneficios.", "Búsqueda de datos.", "Modelado simple.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Precios publicados y reseñas de duración.", "Estudios públicos sobre impacto de fabricación."], "lineamientos": ["Indica de dónde proviene cada cifra y marca las que son estimaciones; evita inventar valores de impacto ambiental.", "No manipules aparatos eléctricos o con baterías por tu cuenta; para la parte de reparación, limítate a consultar costos y opciones."], "otroSector": "La misma lógica sirve para decidir entre mantener o renovar maquinaria, equipos de oficina, vehículos o software."}$a13sld$::jsonb,21),
('guia-para-alargar-la-vida-util-de-los-objetos-cotidianos','ambiente',array['industria','educacion']::text[],'Guía para alargar la vida útil de los objetos cotidianos','Descubre cuánto suelen durar los objetos que usas y qué cuidados sencillos los harían durar más, y reúnelos en una guía clara y práctica.','Guía','~20 h',20,array['Durabilidad','Guía']::text[],array['crear','resolver']::text[],'publicos',NULL,'ingenieria industrial ingenieria mecanica diseno grafico ingenieria ambiental educacion quimica arquitectura comunicaciones investigacion de fuentes. sintesis de informacion. diseno de informacion. redaccion clara. manuales y guias de cuidado de fabricantes. un editor de diseno. hoja de calculo.',$a14sld${"id": "guia-para-alargar-la-vida-util-de-los-objetos-cotidianos", "area": "ambiente", "areas2": ["industria", "educacion"], "titulo": "Guía para alargar la vida útil de los objetos cotidianos", "resumen": "Descubre cuánto suelen durar los objetos que usas y qué cuidados sencillos los harían durar más, y reúnelos en una guía clara y práctica.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Durabilidad", "Guía"], "intencion": ["crear", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Industrial", "Ingeniería Mecánica", "Diseño Gráfico", "Ingeniería Ambiental", "Educación", "Química", "Arquitectura", "Comunicaciones"], "problema": ["Muchos objetos se desechan antes de lo necesario: zapatos mal cuidados, cargadores doblados, ropa mal lavada. Casi nunca se sabe cuánto debería durar un objeto ni qué lo desgasta más rápido.", "Un poco de cuidado puede duplicar la vida de ciertos objetos, pero ese conocimiento se pierde porque nadie lo reúne en un solo lugar."], "desarrollar": ["Elige entre cinco y ocho objetos de uso cotidiano de distintos tipos, como ropa, calzado, cargadores, utensilios o mochilas, y busca en fuentes confiables cuánto suelen durar y qué causa su deterioro.", "Para cada objeto, resume dos o tres cuidados sencillos y presenta todo en una guía visual de una o dos páginas, probándola con alguien que no sea de tu carrera."], "ampliaciones": [{"titulo": "Calendario de cuidado", "aporta": "convierte los consejos en recordatorios sencillos, como limpiar o revisar cada cierto tiempo."}, {"titulo": "Contar lo que dura", "aporta": "registra cuánto duran tus propios objetos durante unos meses."}, {"titulo": "Guía por categoría", "aporta": "profundiza en una sola categoría, como ropa o electrónica."}], "objetivos": ["Identificar qué desgasta cada objeto.", "Reunir cuidados verificables.", "Diseñar una guía clara.", "Probarla con otras personas."], "habilidades": ["Investigación de fuentes.", "Síntesis de información.", "Diseño de información.", "Redacción clara."], "herramientas": ["Manuales y guías de cuidado de fabricantes.", "Un editor de diseño.", "Hoja de cálculo."], "lineamientos": ["Basa los consejos en fuentes verificables y cita las que uses; no repitas trucos caseros sin comprobar que sean seguros.", "No recomiendes abrir ni modificar aparatos eléctricos o con baterías."], "otroSector": "La misma guía sirve para mantener herramientas, equipos de laboratorio, vehículos o instalaciones de un negocio."}$a14sld$::jsonb,22),
('un-objeto-nuevo-sin-comprar-nada-segunda-vida','ambiente',array['arte','industria']::text[],'Un objeto "nuevo" sin comprar nada: segunda vida','Elige algo que ibas a desechar y transfórmalo en un objeto útil, sin comprar materiales, y documenta cómo lo hiciste para que otras personas puedan repetirlo.','Prototipo','~20 h',20,array['Reutilización','Creatividad']::text[],array['crear','resolver']::text[],'propios',NULL,'diseno grafico arquitectura ingenieria industrial ingenieria mecanica educacion ingenieria ambiental administracion quimica diseno y prototipado. resolucion de problemas. documentacion. creatividad aplicada. materiales que ya tengas. herramientas manuales basicas. camara o celular para registrar los pasos.',$a15sld${"id": "un-objeto-nuevo-sin-comprar-nada-segunda-vida", "area": "ambiente", "areas2": ["arte", "industria"], "titulo": "Un objeto \"nuevo\" sin comprar nada: segunda vida", "resumen": "Elige algo que ibas a desechar y transfórmalo en un objeto útil, sin comprar materiales, y documenta cómo lo hiciste para que otras personas puedan repetirlo.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Reutilización", "Creatividad"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Diseño Gráfico", "Arquitectura", "Ingeniería Industrial", "Ingeniería Mecánica", "Educación", "Ingeniería Ambiental", "Administración", "Química"], "problema": ["Muchos objetos llegan a la basura porque parecen no servir para nada, aunque sus materiales todavía sean útiles. Mirarlos con otros ojos es difícil, y por eso la reutilización suele quedarse en ideas de internet que nadie prueba.", "Transformar un objeto es también aprender a evaluar materiales, herramientas y seguridad, y a dejar algo mejor explicado de lo que se encontró."], "desarrollar": ["Elige un objeto o material que ibas a desechar y define para qué podría servir, con un boceto y una lista de lo que necesitarás, usando solo materiales que ya tengas.", "Constrúyelo, registra con fotos los pasos y las dificultades, y prepara una ficha breve que explique cómo repetirlo y qué cuidados tener."], "ampliaciones": [{"titulo": "Medir el ahorro", "aporta": "estima cuánto costaría comprar algo equivalente y cuánto material evitaste desechar."}, {"titulo": "Serie de objetos", "aporta": "crea tres variantes del mismo objeto con residuos distintos."}, {"titulo": "Compartir la técnica", "aporta": "organiza una pequeña muestra o taller para enseñar a otros."}], "objetivos": ["Evaluar el potencial de un material descartado.", "Diseñar y construir un objeto útil.", "Documentar el proceso.", "Reflexionar sobre qué funcionó y qué no."], "habilidades": ["Diseño y prototipado.", "Resolución de problemas.", "Documentación.", "Creatividad aplicada."], "herramientas": ["Materiales que ya tengas.", "Herramientas manuales básicas.", "Cámara o celular para registrar los pasos."], "lineamientos": ["Evita materiales o recipientes que hayan contenido sustancias peligrosas, y usa protección adecuada con herramientas filosas o calientes.", "Si el objeto será usado por niños o para alimentos, verifica que sea seguro o descártalo."], "otroSector": "La misma lógica sirve para reaprovechar materiales en un taller, una escuela, una tienda o un proyecto de diseño."}$a15sld$::jsonb,23)
